def solve_for_n_correct_fraction(n):
    best_min_sum = None
    for p in itertools.permutations(range(1, n + 1)):
        c = [[Fraction(0)]*n for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                c[i][j] = Fraction(1, p[i] + p[j])

        dist = [Fraction(0)] * n
        for j in range(1, n):
            dist[j] = Fraction(0)
            for i in range(j):
                dist[j] = max(dist[j], dist[i] + c[i][j])

        if best_min_sum is None or dist[n-1] < best_min_sum:
            best_min_sum = dist[n-1]
    return best_min_sum

