# For a fixed n, we want to find a permutation p of {1, ..., n}
# that minimizes the longest path in a DAG with weights 1/(p_i + p_j).
# Let's just try random permutations for larger n.

import random

def solve_for_n_random(n, num_samples=1000):
    best_min_sum = None
    for _ in range(num_samples):
        p = list(range(1, n + 1))
        random.shuffle(p)
        c = [[Fraction(0)]*n for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                c[i][j] = Fraction(1, p[i] + p[j])

        dist = [Fraction(0)] * n
        for j in range(1, n):
            dist[j] = Fraction(0)
            for i in range(j):
                dist[j] = max(dist[j], dist[i] + c[i][j])

        if best_min_sum is None or dist[n-1] < best_min_sum:
            best_min_sum = dist[n-1]
    return best_min_sum

for n in range(8, 16):
    print(f"n={n}, best_min_sum={solve_for_n_random(n)}")

